-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Rewriting the application source code to synchronize the two databases automatically","Investigating root causes, enforcing data quality standards, and coordinating resolution","Purchasing new server hardware to improve database replication performance speeds","Approving capital expenditures for a third-party data cleansing vendor contract"]$EXPL$::jsonb,
