-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["To perform daily database backup operations and disaster recovery testing","To establish enterprise-wide data policies and align data management with objectives","To write application source code for the organization''s data management systems","To approve all employee vacation requests and manage staff scheduling"]$EXPL$::jsonb,
