-- Q3522: Data Management and Lifecycle [hard/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["The data warehouse will contain no data and all reports will be blank","Reports will use unconverted currencies, non-standard dates, and duplicate records","The source systems will lose their original data due to the pipeline failure","Users will receive a clear error message when attempting to access reports"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (B): Per COBIT 2019 DSS06, data processing controls must include validation checks to confirm transformations complete successfully. A silent transform failure loads untransformed data, causing currency mismatches, inconsistent date formats, and duplicate records that produce inaccurate financial analysis.
Wrong (A): A silent failure means data still loads into the warehouse, just without proper transformation. The warehouse is not empty; it contains incorrect, untransformed data.
Wrong (C): ETL extracts copies of data from source systems. Source systems retain their original data regardless of whether the ETL transform step succeeds or fails.
Wrong (D): A silent failure by definition does not generate error messages. Users see reports that appear normal while containing materially inaccurate untransformed data.$EXPL$
WHERE id = 3522;

-- Q3523: Data Management and Lifecycle [easy/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["INSERT INTO for adding new records into a table","CREATE TABLE for defining a new table structure","DROP TABLE for permanently removing a table and its data","SELECT ... FROM ... WHERE for retrieving filtered data"]$EXPL$::jsonb,
